steps.run:
set -euo pipefail
# `skipped` is a pass: msrv is gated on `inputs.msrv != ''`.
case "$RESULT" in
  success | skipped) echo "MSRV: $RESULT" ;;
  *) echo "::error::MSRV job did not pass (result: $RESULT)"; exit 1 ;;
esac

case "$RESULT" in
  success) echo "Workspace tests passed" ;;
  *) echo "::error::workspace tests did not pass (result: $RESULT)"; exit 1 ;;
esac
